    40	                <Fut::Output as ResponseSchema>::schema()
    41	            }
    42	        }
    43	    };
    44	}
    45	
    46	handler_schema!();
    47	handler_schema!(A);
    48	handler_schema!(A, B);
    49	handler_schema!(A, B, C);
    50	
    51	fn section(label: &str, schema: &Schema) -> String {
    52	    format!(
    53	        "{label}\n{}\n",
    54	        serde_json::to_string_pretty(schema).expect("JSON schema serializes")
    55	    )
    56	}
    57	
    58	fn failure() -> String {
    59	    format!(
    60	        "Success: one JSON document on stdout, exit 0.\nCommand failure: one JSON document on stderr, exit 1.\nClap argument errors and help use Clap's text output.\nSchemas use JSON Schema draft 2020-12.\n\n{}",
    61	        section("Failure JSON schema:", &schema::<ErrorResponse>())
    62	    )
    63	}
    64	
    65	pub(super) fn single<Args>(handler: impl HandlerSchema<Args>) -> String {
    66	    format!(
    67	        "{}\n{}",
    68	        section("Success JSON schema:", &handler.response_schema()),
    69	        failure()
    70	    )
    71	}
    72	
    73	pub(super) fn declarations() -> String {
    74	    let mut help = String::new();
    75	    for stage in DeclarationIngestionStage::iter() {
    76	        let mut schema = match stage {
    77	            DeclarationIngestionStage::Fetch => super::fetch_declarations.response_schema(),
    78	            DeclarationIngestionStage::Clean => super::clean_declarations.response_schema(),
    79	            DeclarationIngestionStage::Resolve => super::resolve_declarations.response_schema(),
    80	            DeclarationIngestionStage::Load => super::load_declarations.response_schema(),
    81	        };
    82	        if stage == DeclarationIngestionStage::Fetch {
    83	            schema
    84	                .as_object_mut()
    85	                .expect("response schema is an object")["properties"]["stage"]["const"] =
    86	                serde_json::to_value(&stage).expect("stage serializes");
    87	        }
    88	        let label = serde_json::to_value(&stage).expect("stage serializes");
    89	        help.push_str(&section(
    90	            &format!(
    91	                "Success JSON schema ({}):",
    92	                label.as_str().expect("stage is a string")
    93	            ),
    94	            &schema,
    95	        ));
    96	        help.push('\n');
    97	    }
    98	    help.push_str(&failure());
    99	    help
   100	}
"}
